 import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, texture, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    Color,
    DoubleSide,
    PointLight,
    DirectionalLight
  } = ctx.THREE;

  const colors = {
    ink: new Color(config.intent?.visualSpec?.colors?.ink ?? '#16161d'),
    paper: new Color(config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2'),
    accent: new Color(config.intent?.visualSpec?.colors?.accent ?? '#ff2a38'),
    surface: new Color(config.intent?.visualSpec?.colors?.surface ?? '#0b0b10')
  };

  const group = new Group();

  // Stage backdrop: vertical ink-to-surface gradient.
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    side: DoubleSide
  });
  backdropMat.colorNode = mix(
    color(colors.surface),
    color(colors.ink),
    smoothstep(0.0, 1.0, uv().y)
  );
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Card assembly
  const cardGroup = new Group();
  group.add(cardGroup);

  // Aspect from atlas rect 512x320 == 1.6
  const cardWidth = 2.0;
  const cardHeight = cardWidth / 1.6; // 1.25

  // Accent edge / rim backing
  const rimGeo = new PlaneGeometry(cardWidth + 0.06, cardHeight + 0.06);
  const rimMat = new MeshStandardNodeMaterial({
    color: 0x000000,
    emissive: 0x000000,
    emissiveIntensity: 0,
    metalness: 0.5,
    roughness: 0.7
  });
  const rim = new Mesh(rimGeo, rimMat);
  rim.position.z = -0.05;
  cardGroup.add(rim);

  // Image plane
  const imageGeo = new PlaneGeometry(cardWidth, cardHeight);
  const imageMat = new MeshBasicNodeMaterial({ transparent: true });
  const imageMesh = new Mesh(imageGeo, imageMat);
  cardGroup.add(imageMesh);

  // Bottom caption strip (unlabeled because no textContent provided)
  const stripHeight = cardHeight * 0.22;
  const stripGeo = new PlaneGeometry(cardWidth, stripHeight);
  const stripMat = new MeshStandardNodeMaterial({
    color: colors.ink,
    metalness: 0.45,
    roughness: 0.65
  });
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, -cardHeight / 2 + stripHeight / 2, 0.01);
  cardGroup.add(strip);

  // Node-local lighting
  const keyLight = new DirectionalLight(colors.paper, 1.0);
  keyLight.position.set(2, 3, 4);
  cardGroup.add(keyLight);

  const accentRimLight = new PointLight(colors.accent, 0.8, 8);
  accentRimLight.position.set(-1.5, 1, 2.5);
  cardGroup.add(accentRimLight);

  // Texture load
  let loadedTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
      loadedTex = tex;
      imageMat.colorNode = texture(tex).toColorSpace(ctx.THREE.SRGBColorSpace);
      imageMat.opacityNode = texture(tex).a;
      imageMat.needsUpdate = true;
    });
  }

  // Motion timelines
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(
    cardGroup.position,
    { z: 0.15, duration: 0.45, ease: 'power2.out' },
    0
  );
  hoverTl.to(
    rimMat.emissive,
    { r: colors.accent.r, g: colors.accent.g, b: colors.accent.b, duration: 0.35, ease: 'power2.out' },
    0
  );
  hoverTl.to(
    rimMat,
    { emissiveIntensity: 1.2, duration: 0.35, ease: 'power2.out' },
    0
  );

  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(
    cardGroup.scale,
    { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' },
    0
  );

  // Interaction handlers
  let isHovered = false;
  let isPressed = false;

  group.userData.handlers = {
    pointerenter: () => {
      isHovered = true;
      hoverTl.play();
    },
    pointerleave: () => {
      isHovered = false;
      isPressed = false;
      hoverTl.reverse();
      pressTl.reverse();
    },
    pointerdown: () => {
      isPressed = true;
      pressTl.play();
    },
    pointerup: () => {
      isPressed = false;
      pressTl.reverse();
    },
    click: () => {
      ctx.emit('hub-journal.select', { id: config.id });
    },
    focus: () => {
      if (!isHovered) hoverTl.play();
    },
    blur: () => {
      if (!isHovered) hoverTl.reverse();
    }
  };

  group.userData.cleanup = () => {
    hoverTl.kill();
    pressTl.kill();

    backdropGeo.dispose();
    backdropMat.dispose();

    rimGeo.dispose();
    rimMat.dispose();

    imageGeo.dispose();
    imageMat.dispose();

    stripGeo.dispose();
    stripMat.dispose();

    if (loadedTex) loadedTex.dispose();

    keyLight.dispose();
    accentRimLight.dispose();
  };

  return group;
}
